import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { useQuery } from "@tanstack/react-query";
import { TrendingUp, TrendingDown, BarChart3 } from "lucide-react";
import { useLanguage } from "@/contexts/LanguageContext";

interface BitcoinData {
  price: number;
  change24h: number;
  high24h: number;
  low24h: number;
  volume24h: number;
  marketCap: number;
  priceHistory: Array<{ time: string; price: number }>;
}

interface MarketAnalysis {
  trend: 'bullish' | 'bearish' | 'neutral';
  support: number;
  resistance: number;
  recommendation: string;
  rsi: number;
  sentiment: string;
}

export default function BitcoinChart() {
  const { t } = useLanguage();

  // Fetch real Bitcoin data from public APIs
  const { data: bitcoinData, isLoading: bitcoinLoading } = useQuery<BitcoinData>({
    queryKey: ['/api/bitcoin-real-data'],
    refetchInterval: 30000, // Update every 30 seconds
  });

  const { data: marketAnalysis, isLoading: analysisLoading } = useQuery<MarketAnalysis>({
    queryKey: ['/api/market-analysis'],
    refetchInterval: 300000, // Update every 5 minutes
  });

  if (bitcoinLoading) {
    return (
      <div className="grid lg:grid-cols-2 gap-8" data-testid="bitcoin-chart-loading">
        <Card>
          <CardContent className="p-8">
            <div className="animate-pulse">
              <div className="h-4 bg-gray-200 rounded mb-4"></div>
              <div className="h-32 bg-gray-200 rounded mb-4"></div>
              <div className="h-4 bg-gray-200 rounded"></div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-8">
            <div className="animate-pulse">
              <div className="h-4 bg-gray-200 rounded mb-4"></div>
              <div className="h-32 bg-gray-200 rounded mb-4"></div>
              <div className="h-4 bg-gray-200 rounded"></div>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  const formatPrice = (price: number) => {
    return new Intl.NumberFormat('vi-VN', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(price);
  };

  const formatVolume = (volume: number) => {
    if (volume >= 1e9) {
      return `$${(volume / 1e9).toFixed(2)}B`;
    } else if (volume >= 1e6) {
      return `$${(volume / 1e6).toFixed(2)}M`;
    }
    return `$${volume.toLocaleString()}`;
  };

  return (
    <section className="py-20 bg-gray-50" data-testid="section-bitcoin-chart">
      <div className="container mx-auto px-4">
        <div className="text-center mb-16">
          <h2 className="text-4xl font-bold text-dark-slate mb-4" data-testid="text-chart-title">
            Biểu đồ Bitcoin Thời gian Thực
          </h2>
          <p className="text-xl text-gray-600 max-w-3xl mx-auto" data-testid="text-chart-description">
            Dữ liệu giá Bitcoin cập nhật trực tiếp từ các sàn giao dịch hàng đầu thế giới
          </p>
        </div>

        <div className="grid lg:grid-cols-2 gap-8 max-w-7xl mx-auto">
          {/* Bitcoin Price Card */}
          <Card className="shadow-lg" data-testid="card-bitcoin-price">
            <CardHeader>
              <CardTitle className="flex items-center space-x-2">
                <BarChart3 className="text-bitcoin h-6 w-6" />
                <span>Giá Bitcoin (BTC/USD)</span>
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6">
              <div className="space-y-6">
                {/* Current Price */}
                <div className="text-center">
                  <div className="text-4xl font-bold text-dark-slate mb-2" data-testid="text-current-price">
                    {bitcoinData ? formatPrice(bitcoinData.price) : '$--,---'}
                  </div>
                  <div className={`flex items-center justify-center space-x-2 text-lg font-semibold ${
                    bitcoinData && bitcoinData.change24h >= 0 ? 'text-green-500' : 'text-red-500'
                  }`} data-testid="text-price-change">
                    {bitcoinData && bitcoinData.change24h >= 0 ? (
                      <TrendingUp className="h-5 w-5" />
                    ) : (
                      <TrendingDown className="h-5 w-5" />
                    )}
                    <span>
                      {bitcoinData ? `${bitcoinData.change24h >= 0 ? '+' : ''}${bitcoinData.change24h.toFixed(2)}%` : '-%'}
                    </span>
                    <span className="text-gray-500 text-sm">24h</span>
                  </div>
                </div>

                {/* Price Stats */}
                <div className="grid grid-cols-2 gap-4">
                  <div className="bg-gray-50 p-4 rounded-lg" data-testid="stat-high24h">
                    <div className="text-sm text-gray-600 mb-1">Cao nhất 24h</div>
                    <div className="text-lg font-semibold text-dark-slate">
                      {bitcoinData ? formatPrice(bitcoinData.high24h) : '$--,---'}
                    </div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg" data-testid="stat-low24h">
                    <div className="text-sm text-gray-600 mb-1">Thấp nhất 24h</div>
                    <div className="text-lg font-semibold text-dark-slate">
                      {bitcoinData ? formatPrice(bitcoinData.low24h) : '$--,---'}
                    </div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg" data-testid="stat-volume24h">
                    <div className="text-sm text-gray-600 mb-1">Khối lượng 24h</div>
                    <div className="text-lg font-semibold text-dark-slate">
                      {bitcoinData ? formatVolume(bitcoinData.volume24h) : '$--B'}
                    </div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg" data-testid="stat-market-cap">
                    <div className="text-sm text-gray-600 mb-1">Vốn hóa thị trường</div>
                    <div className="text-lg font-semibold text-dark-slate">
                      {bitcoinData ? formatVolume(bitcoinData.marketCap) : '$--B'}
                    </div>
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Market Analysis Card */}
          <Card className="shadow-lg" data-testid="card-market-analysis">
            <CardHeader>
              <CardTitle className="flex items-center space-x-2">
                <TrendingUp className="text-green-500 h-6 w-6" />
                <span>Phân tích Thị trường</span>
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6">
              {analysisLoading ? (
                <div className="animate-pulse space-y-4">
                  <div className="h-4 bg-gray-200 rounded"></div>
                  <div className="h-4 bg-gray-200 rounded"></div>
                  <div className="h-4 bg-gray-200 rounded"></div>
                </div>
              ) : (
                <div className="space-y-6">
                  {/* Market Trend */}
                  <div className="flex items-center justify-between p-4 bg-gray-50 rounded-lg" data-testid="market-trend">
                    <span className="text-gray-600">Xu hướng thị trường:</span>
                    <span className={`font-semibold px-3 py-1 rounded-full text-sm ${
                      marketAnalysis?.trend === 'bullish' 
                        ? 'bg-green-100 text-green-700' 
                        : marketAnalysis?.trend === 'bearish' 
                        ? 'bg-red-100 text-red-700' 
                        : 'bg-yellow-100 text-yellow-700'
                    }`}>
                      {marketAnalysis?.trend === 'bullish' 
                        ? 'Tăng giá' 
                        : marketAnalysis?.trend === 'bearish' 
                        ? 'Giảm giá' 
                        : 'Trung tính'}
                    </span>
                  </div>

                  {/* Support & Resistance */}
                  <div className="grid grid-cols-2 gap-4">
                    <div className="bg-red-50 p-4 rounded-lg" data-testid="support-level">
                      <div className="text-sm text-red-600 mb-1">Hỗ trợ</div>
                      <div className="text-lg font-semibold text-red-700">
                        {marketAnalysis ? formatPrice(marketAnalysis.support) : '$--,---'}
                      </div>
                    </div>
                    <div className="bg-green-50 p-4 rounded-lg" data-testid="resistance-level">
                      <div className="text-sm text-green-600 mb-1">Kháng cự</div>
                      <div className="text-lg font-semibold text-green-700">
                        {marketAnalysis ? formatPrice(marketAnalysis.resistance) : '$--,---'}
                      </div>
                    </div>
                  </div>

                  {/* RSI */}
                  <div className="bg-blue-50 p-4 rounded-lg" data-testid="rsi-indicator">
                    <div className="flex items-center justify-between mb-2">
                      <span className="text-sm text-blue-600">RSI (14)</span>
                      <span className="text-lg font-semibold text-blue-700">
                        {marketAnalysis ? `${marketAnalysis.rsi.toFixed(1)}` : '--'}
                      </span>
                    </div>
                    <div className="w-full bg-gray-200 rounded-full h-2">
                      <div 
                        className="bg-blue-500 h-2 rounded-full" 
                        style={{ width: `${marketAnalysis ? marketAnalysis.rsi : 0}%` }}
                      ></div>
                    </div>
                  </div>

                  {/* Recommendation */}
                  <div className="p-4 bg-bitcoin/10 border border-bitcoin/20 rounded-lg" data-testid="recommendation">
                    <div className="text-sm text-bitcoin font-medium mb-2">Khuyến nghị AI:</div>
                    <div className="text-dark-slate">
                      {marketAnalysis?.recommendation || 'Đang phân tích...'}
                    </div>
                  </div>

                  {/* Sentiment */}
                  <div className="text-center p-4 bg-gray-50 rounded-lg" data-testid="market-sentiment">
                    <div className="text-sm text-gray-600 mb-1">Tâm lý thị trường</div>
                    <div className="text-lg font-semibold text-dark-slate">
                      {marketAnalysis?.sentiment || 'Đang cập nhật...'}
                    </div>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>
        </div>

        {/* Real-time Update Notice */}
        <div className="text-center mt-8">
          <p className="text-sm text-gray-500" data-testid="text-update-notice">
            Dữ liệu cập nhật mỗi 30 giây từ các sàn giao dịch Bitcoin uy tín thế giới
          </p>
        </div>
      </div>
    </section>
  );
}

client/src/components/contact-support.ts.content:
import { useState } from "react";
import { useMutation } from "@tanstack/react-query";
import { Mail, Phone, MapPin, MessageCircle, Video, HelpCircle, Book, Send, Info } from "lucide-react";
import { SiFacebook } from "react-icons/si";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Card, CardContent } from "@/components/ui/card";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { useLanguage } from "@/contexts/LanguageContext";

interface ContactFormData {
  name: string;
  email: string;
  phone: string;
  subject: string;
  message: string;
}

export default function ContactSupport() {
  const { t } = useLanguage();
  const { toast } = useToast();
  const [formData, setFormData] = useState<ContactFormData>({
    name: "",
    email: "",
    phone: "",
    subject: "",
    message: ""
  });
  const [privacyAccepted, setPrivacyAccepted] = useState(false);

  const contactMutation = useMutation({
    mutationFn: async (data: ContactFormData) => {
      const response = await apiRequest("POST", "/api/contact", data);
      return response.json();
    },
    onSuccess: (data) => {
      toast({
        title: t('common.success'),
        description: data.message || t('contact.send_success'),
      });
      setFormData({
        name: "",
        email: "",
        phone: "",
        subject: "",
        message: ""
      });
      setPrivacyAccepted(false);
    },
    onError: (error: any) => {
      toast({
        title: t('common.error'),
        description: error.message || t('contact.send_error'),
        variant: "destructive",
      });
    },
  });

  const handleInputChange = (field: keyof ContactFormData, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!privacyAccepted) {
      toast({
        title: t('common.error'),
        description: t('contact.privacy_required'),
        variant: "destructive",
      });
      return;
    }

    if (!formData.name || !formData.email || !formData.subject || !formData.message) {
      toast({
        title: t('common.error'),
        description: t('contact.all_fields_required'),
        variant: "destructive",
      });
      return;
    }

    contactMutation.mutate(formData);
  };

  const supportOptions = [
    {
      icon: MessageCircle,
      title: t('contact.support_options.live_chat'),
      subtitle: t('contact.support_options.live_chat_subtitle'),
      color: "text-bitcoin"
    },
    {
      icon: Video,
      title: t('contact.support_options.video_call'),
      subtitle: t('contact.support_options.video_call_subtitle'),
      color: "text-bitcoin"
    },
    {
      icon: HelpCircle,
      title: t('contact.support_options.faq'),
      subtitle: t('contact.support_options.faq_subtitle'),
      color: "text-bitcoin"
    },
    {
      icon: Book,
      title: t('contact.support_options.guide'),
      subtitle: t('contact.support_options.guide_subtitle'),
      color: "text-bitcoin"
    }
  ];

  return (
    <section id="contact" className="py-20 bg-white" data-testid="section-contact">
      <div className="container mx-auto px-4">
        <div className="text-center mb-16">
          <h2 className="text-4xl font-bold text-dark-slate mb-4" data-testid="text-contact-title">
            {t('contact.title')}
          </h2>
          <p className="text-xl text-gray-600 max-w-3xl mx-auto" data-testid="text-contact-description">
            {t('contact.description')}
          </p>
        </div>

        <div className="grid lg:grid-cols-2 gap-12 max-w-6xl mx-auto">
          {/* Contact Information */}
          <div className="space-y-8">
            <Card className="bg-gradient-to-br from-bitcoin to-bitcoin-light text-white" data-testid="card-contact-info">
              <CardContent className="p-8">
                <h3 className="text-2xl font-bold mb-6">{t('contact.info.title')}</h3>

                <div className="space-y-6">
                  <div className="flex items-start space-x-4" data-testid="contact-email">
                    <div className="w-12 h-12 bg-white/20 rounded-lg flex items-center justify-center flex-shrink-0">
                      <Mail className="text-white text-xl h-6 w-6" />
                    </div>
                    <div>
                      <div className="font-semibold mb-1">Email</div>
                      <a href="mailto:haidh1975@gmail.com" className="opacity-90 hover:opacity-100" data-testid="link-email">
                        haidh1975@gmail.com
                      </a>
                      <div className="text-sm opacity-75">{t('contact.response_time')}</div>
                    </div>
                  </div>

                  <div className="flex items-start space-x-4" data-testid="contact-phone">
                    <div className="w-12 h-12 bg-white/20 rounded-lg flex items-center justify-center flex-shrink-0">
                      <Phone className="text-white text-xl h-6 w-6" />
                    </div>
                    <div>
                      <div className="font-semibold mb-1">{t('contact.form.phone')}</div>
                      <a href="tel:+84888151975" className="opacity-90 hover:opacity-100" data-testid="link-phone">
                        +84 888 151 975
                      </a>
                      <div className="text-sm opacity-75">{t('contact.support_247')}</div>
                    </div>
                  </div>

                  <div className="flex items-start space-x-4" data-testid="contact-address">
                    <div className="w-12 h-12 bg-white/20 rounded-lg flex items-center justify-center flex-shrink-0">
                      <MapPin className="text-white text-xl h-6 w-6" />
                    </div>
                    <div>
                      <div className="font-semibold mb-1">{t('contact.form.subject')}</div>
                      <div className="opacity-90">Số 25, ngõ 155 đường Cầu Giấy</div>
                      <div className="opacity-90">Phường Quan Giấy, TP. Hà Nội</div>
                      <div className="text-sm opacity-75">Giờ làm việc: 8:00 - 22:00</div>
                    </div>
                  </div>

                  <div className="flex items-start space-x-4" data-testid="contact-facebook">
                    <div className="w-12 h-12 bg-white/20 rounded-lg flex items-center justify-center flex-shrink-0">
                      <SiFacebook className="text-white text-xl h-6 w-6" />
                    </div>
                    <div>
                      <div className="font-semibold mb-1">Facebook</div>
                      <a 
                        href="https://www.facebook.com/profile.php?id=100067837153049" 
                        target="_blank" 
                        rel="noopener noreferrer"
                        className="opacity-90 hover:opacity-100"
                        data-testid="link-facebook"
                      >
                        HHDcoin Official
                      </a>
                      <div className="text-sm opacity-75">Cập nhật tin tức mới nhất</div>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Support Options */}
            <Card className="bg-gray-50" data-testid="card-support-options">
              <CardContent className="p-8">
                <h3 className="text-2xl font-bold text-dark-slate mb-6">{t('contact.live_support')}</h3>

                <div className="grid grid-cols-2 gap-4">
                  {supportOptions.map((option, index) => (
                    <Button
                      key={index}
                      variant="outline"
                      className="bg-white border border-gray-200 rounded-lg p-4 text-center hover:border-bitcoin transition-colors h-auto flex flex-col items-center"
                      data-testid={`button-support-option-${index}`}
                    >
                      <option.icon className={`${option.color} text-2xl mb-2 h-8 w-8`} />
                      <div className="font-semibold text-dark-slate">{option.title}</div>
                      <div className="text-sm text-gray-600">{option.subtitle}</div>
                    </Button>
                  ))}
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Contact Form */}
          <Card className="bg-gray-50" data-testid="card-contact-form">
            <CardContent className="p-8">
              <h3 className="text-2xl font-bold text-dark-slate mb-6">{t('contact.form.send')}</h3>

              <form onSubmit={handleSubmit} className="space-y-6">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label htmlFor="name" className="block text-sm font-medium text-gray-700 mb-2">
                      {t('contact.form.name')} *
                    </Label>
                    <Input
                      id="name"
                      type="text"
                      placeholder="Nhập họ tên..." 
                      value={formData.name}
                      onChange={(e) => handleInputChange("name", e.target.value)}
                      required
                      data-testid="input-name"
                    />
                  </div>
                  <div>
                    <Label htmlFor="phone" className="block text-sm font-medium text-gray-700 mb-2">
                      {t('contact.form.phone')}
                    </Label>
                    <Input
                      id="phone"
                      type="tel"
                      placeholder="Nhập số điện thoại..." 
                      value={formData.phone}
                      onChange={(e) => handleInputChange("phone", e.target.value)}
                      data-testid="input-phone"
                    />
                  </div>
                </div>

                <div>
                  <Label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-2">
                    Email *
                  </Label>
                  <Input
                    id="email"
                    type="email"
                    placeholder="Nhập email..." 
                    value={formData.email}
                    onChange={(e) => handleInputChange("email", e.target.value)}
                    required
                    data-testid="input-email"
                  />
                </div>

                <div>
                  <Label htmlFor="subject" className="block text-sm font-medium text-gray-700 mb-2">
                    {t('contact.form.subject')} *
                  </Label>
                  <Select value={formData.subject} onValueChange={(value) => handleInputChange("subject", value)}>
                    <SelectTrigger data-testid="select-subject">
                      <SelectValue placeholder="Chọn chủ đề..." />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="investment">Tư vấn đầu tư</SelectItem>
                      <SelectItem value="technical">Hỗ trợ kỹ thuật</SelectItem>
                      <SelectItem value="partnership">Hợp tác kinh doanh</SelectItem>
                      <SelectItem value="other">Khác</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <Label htmlFor="message" className="block text-sm font-medium text-gray-700 mb-2">
                    {t('contact.form.message')} *
                  </Label>
                  <Textarea
                    id="message"
                    rows={5}
                    placeholder="Nhập nội dung tin nhắn..." 
                    value={formData.message}
                    onChange={(e) => handleInputChange("message", e.target.value)}
                    className="resize-none"
                    required
                    data-testid="textarea-message"
                  />
                </div>

                <div className="flex items-start space-x-3">
                  <Checkbox 
                    id="privacy" 
                    checked={privacyAccepted}
                    onCheckedChange={(checked) => setPrivacyAccepted(checked as boolean)}
                    data-testid="checkbox-privacy"
                  />
                  <Label htmlFor="privacy" className="text-sm text-gray-600 leading-relaxed">
                    {t('contact.privacy_policy')}
                  </Label>
                </div>

                <Button 
                  type="submit" 
                  className="w-full bg-bitcoin text-white py-4 rounded-lg font-semibold hover:bg-bitcoin-light transition-colors"
                  disabled={contactMutation.isPending}
                  data-testid="button-send-message"
                >
                  <Send className="mr-2 h-5 w-5" />
                  {contactMutation.isPending ? t('contact.form.sending') : t('contact.form.send')}
                </Button>
              </form>

              <div className="mt-6 p-4 bg-blue-50 border border-blue-200 rounded-lg" data-testid="info-response-time">
                <div className="flex items-start space-x-3">
                  <Info className="text-blue-500 mt-1 h-5 w-5 flex-shrink-0" />
                  <div className="text-sm text-blue-700">
                    <strong>Lưu ý:</strong> Chúng tôi cam kết phản hồi mọi tin nhắn trong vòng 2 giờ làm việc. 
                    Đối với các vấn đề khẩn cấp, vui lòng gọi trực tiếp hotline.
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </section>
  );
}

