import { useState } from "react";
import { useLocation } from "wouter";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { useAuth } from "@/hooks/useAuth";
import { useLanguage } from "@/contexts/LanguageContext";
import Navigation from "@/components/navigation";
import { 
  Bitcoin, 
  TrendingUp, 
  Shield, 
  Users, 
  CheckCircle, 
  ArrowLeft,
  CreditCard,
  DollarSign 
} from "lucide-react";

interface InvestmentPackage {
  id: string;
  name: string;
  minInvestment: string;
  minRate: string;
  maxRate: string;
  features: string[];
  recommended: number;
}

function InvestmentPurchase() {
  const [, setLocation] = useLocation();
  const { user, isAuthenticated } = useAuth();
  const { toast } = useToast();
  const { t } = useLanguage();
  const [selectedPackage, setSelectedPackage] = useState<string>("");
  const [investmentAmount, setInvestmentAmount] = useState<string>("");
  const [isProcessing, setIsProcessing] = useState(false);

  // Get packages data
  const { data: packages = [], isLoading: packagesLoading } = useQuery({
    queryKey: ["/api/investment-packages"],
  });

  // Create payment intent mutation
  const createPaymentMutation = useMutation({
    mutationFn: async (data: { packageId: string; amount: number }) => {
      const response = await apiRequest("POST", "/api/create-payment-intent", {
        packageId: data.packageId,
        amount: data.amount,
        currency: "vnd"
      });
      return response.json();
    },
    onSuccess: (data: any) => {
      if (data.clientSecret) {
        // Redirect to checkout page securely - no sensitive data in URL
        setLocation(`/checkout?package=${selectedPackage}&amount=${investmentAmount}&transaction_id=${data.transactionId}`);
      }
    },
    onError: (error: any) => {
      toast({
        title: t('purchase.error_payment'),
        description: error.message || t('purchase.error_payment_desc'),
        variant: "destructive",
      });
      setIsProcessing(false);
    },
  });

  const selectedPackageData = (packages as InvestmentPackage[]).find((pkg: InvestmentPackage) => pkg.id === selectedPackage);

  const formatCurrency = (amount: string) => {
    return new Intl.NumberFormat('vi-VN', {
      style: 'currency',
      currency: 'VND'
    }).format(parseInt(amount));
  };

  const handlePurchase = async () => {
    if (!isAuthenticated) {
      toast({
        title: t('purchase.login_required'),
        description: t('purchase.login_message'),
        variant: "destructive",
      });
      setLocation("/login");
      return;
    }

    if (!selectedPackage) {
      toast({
        title: t('purchase.error_no_package'),
        description: t('purchase.error_no_package_desc'),
        variant: "destructive",
      });
      return;
    }

    const amount = parseInt(investmentAmount.replace(/\D/g, ''));
    if (!amount || amount <= 0) {
      toast({
        title: t('purchase.error_invalid_amount'),
        description: t('purchase.error_invalid_amount_desc'),
        variant: "destructive",
      });
      return;
    }

    if (selectedPackageData && amount < parseInt(selectedPackageData.minInvestment)) {
      toast({
        title: t('purchase.error_amount_too_low'),
        description: t('purchase.error_amount_too_low_desc', { amount: formatCurrency(selectedPackageData.minInvestment) }),
        variant: "destructive",
      });
      return;
    }

    setIsProcessing(true);
    createPaymentMutation.mutate({ packageId: selectedPackage, amount });
  };

  const handleAmountChange = (value: string) => {
    // Remove non-numeric characters and format
    const numericValue = value.replace(/\D/g, '');
    const formattedValue = new Intl.NumberFormat('vi-VN').format(parseInt(numericValue) || 0);
    setInvestmentAmount(formattedValue === '0' ? '' : formattedValue);
  };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-orange-50 to-blue-50 dark:from-gray-900 dark:to-gray-800">
        <Navigation />
        <div className="pt-20 pb-16">
          <div className="container mx-auto px-4">
            <Card className="max-w-md mx-auto">
              <CardHeader className="text-center">
                <CardTitle className="text-2xl font-bold text-orange-600 dark:text-orange-400">
                  {t('purchase.login_required')}
                </CardTitle>
              </CardHeader>
              <CardContent className="text-center space-y-4">
                <p className="text-gray-600 dark:text-gray-300">
                  {t('purchase.login_message')}
                </p>
                <Button onClick={() => setLocation("/login")} className="w-full" data-testid="button-login">
                  {t('login.login_button')}
                </Button>
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-50 to-blue-50 dark:from-gray-900 dark:to-gray-800">
      <Navigation />

      <div className="pt-20 pb-16">
        <div className="container mx-auto px-4">
          {/* Header */}
          <div className="mb-8">
            <Button 
              variant="ghost" 
              onClick={() => setLocation("/investment-packages")}
              className="mb-4"
              data-testid="button-back"
            >
              <ArrowLeft className="h-4 w-4 mr-2" />
              {t('purchase.back_to_packages')}
            </Button>

            <div className="text-center">
              <h1 className="text-4xl font-bold text-gray-900 dark:text-white mb-2">
                {t('purchase.title')}
              </h1>
              <p className="text-lg text-gray-600 dark:text-gray-300">
                {t('purchase.subtitle')}
              </p>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 max-w-6xl mx-auto">
            {/* Package Selection */}
            <div className="space-y-6">
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2" data-testid="title-package-selection">
                    <Bitcoin className="h-5 w-5 text-orange-500" />
                    {t('purchase.select_package')}
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  {packagesLoading ? (
                    <div className="space-y-4">
                      {[1, 2, 3].map((i) => (
                        <div key={i} className="h-32 bg-gray-200 dark:bg-gray-700 rounded-lg animate-pulse" />
                      ))}
                    </div>
                  ) : (
                    (packages as InvestmentPackage[]).map((pkg: InvestmentPackage) => (
                      <Card 
                        key={pkg.id}
                        className={`cursor-pointer transition-all hover:shadow-lg ${
                          selectedPackage === pkg.id 
                            ? 'ring-2 ring-orange-500 shadow-lg' 
                            : ''
                        } ${pkg.recommended ? 'border-orange-300 dark:border-orange-600' : ''}`}
                        onClick={() => setSelectedPackage(pkg.id)}
                        data-testid={`card-package-${pkg.id}`}
                      >
                        <CardContent className="p-4">
                          <div className="flex justify-between items-start mb-2">
                            <h3 className="font-semibold text-lg">{pkg.name}</h3>
                            {pkg.recommended === 1 && (
                              <Badge variant="default" className="bg-orange-500 text-white">
                                {t('purchase.recommended')}
                              </Badge>
                            )}
                          </div>

                          <div className="space-y-2 text-sm">
                            <div className="flex items-center justify-between">
                              <span className="text-gray-600 dark:text-gray-400">{t('purchase.min_investment')}</span>
                              <span className="font-medium">{formatCurrency(pkg.minInvestment)}</span>
                            </div>
                            <div className="flex items-center justify-between">
                              <span className="text-gray-600 dark:text-gray-400">{t('purchase.profit_range')}</span>
                              <span className="font-medium text-green-600 dark:text-green-400">
                                {pkg.minRate}% - {pkg.maxRate}%
                              </span>
                            </div>
                          </div>

                          <div className="mt-3 flex flex-wrap gap-1">
                            {pkg.features.slice(0, 2).map((feature: string, index: number) => (
                              <Badge key={index} variant="secondary" className="text-xs">
                                {feature.replace(/^[^:]*:\s*/, '')}
                              </Badge>
                            ))}
                          </div>
                        </CardContent>
                      </Card>
                    ))
                  )}
                </CardContent>
              </Card>

              {/* Investment Amount */}
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2" data-testid="title-investment-amount">
                    <DollarSign className="h-5 w-5 text-green-500" />
                    {t('purchase.investment_amount')}
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div>
                    <Label htmlFor="amount">{t('purchase.amount_vnd')}</Label>
                    <Input
                      id="amount"
                      type="text"
                      placeholder={t('purchase.enter_amount')}
                      value={investmentAmount}
                      onChange={(e) => handleAmountChange(e.target.value)}
                      className="text-lg"
                      data-testid="input-investment-amount"
                    />
                    {selectedPackageData && (
                      <p className="text-sm text-gray-500 mt-1">
                        {t('purchase.minimum')} {formatCurrency(selectedPackageData.minInvestment)}
                      </p>
                    )}
                  </div>
                </CardContent>
              </Card>
            </div>

            {/* Purchase Summary */}
            <div className="space-y-6">
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2" data-testid="title-purchase-summary">
                    <CreditCard className="h-5 w-5 text-blue-500" />
                    {t('purchase.summary')}
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  {selectedPackageData ? (
                    <div className="space-y-4">
                      <div>
                        <h3 className="font-semibold text-lg mb-2">{selectedPackageData.name}</h3>
                        <div className="space-y-2 text-sm">
                          <div className="flex justify-between">
                            <span>{t('purchase.expected_profit')}</span>
                            <span className="font-medium text-green-600 dark:text-green-400">
                              {selectedPackageData.minRate}% - {selectedPackageData.maxRate}%
                            </span>
                          </div>
                          {investmentAmount && (
                            <div className="flex justify-between">
                              <span>{t('purchase.investment_amount_label')}</span>
                              <span className="font-medium">
                                {new Intl.NumberFormat('vi-VN', {
                                  style: 'currency',
                                  currency: 'VND'
                                }).format(parseInt(investmentAmount.replace(/\D/g, '')) || 0)}
                              </span>
                            </div>
                          )}
                        </div>
                      </div>

                      <Separator />

                      <div className="space-y-2">
                        <h4 className="font-medium">{t('purchase.package_benefits')}</h4>
                        <ul className="space-y-1 text-sm">
                          {selectedPackageData.features.map((feature: string, index: number) => (
                            <li key={index} className="flex items-center gap-2">
                              <CheckCircle className="h-4 w-4 text-green-500 flex-shrink-0" />
                              <span>{feature}</span>
                            </li>
                          ))}
                        </ul>
                      </div>

                      <Separator />

                      <Button 
                        onClick={handlePurchase}
                        disabled={!selectedPackage || !investmentAmount || isProcessing}
                        className="w-full bg-orange-600 hover:bg-orange-700 text-white"
                        data-testid="button-purchase"
                      >
                        {isProcessing ? t('purchase.processing') : t('purchase.pay_now')}
                      </Button>
                    </div>
                  ) : (
                    <div className="text-center py-8 text-gray-500 dark:text-gray-400">
                      <Bitcoin className="h-12 w-12 mx-auto mb-4 opacity-50" />
                      <p>{t('purchase.select_package_prompt')}</p>
                    </div>
                  )}
                </CardContent>
              </Card>

              {/* Benefits */}
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <TrendingUp className="h-5 w-5 text-purple-500" />
                    {t('purchase.benefits_title')}
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-3 text-sm">
                    <div className="flex items-center gap-3">
                      <Shield className="h-5 w-5 text-blue-500 flex-shrink-0" />
                      <span>{t('purchase.benefit_security')}</span>
                    </div>
                    <div className="flex items-center gap-3">
                      <TrendingUp className="h-5 w-5 text-green-500 flex-shrink-0" />
                      <span>{t('purchase.benefit_ai')}</span>
                    </div>
                    <div className="flex items-center gap-3">
                      <Users className="h-5 w-5 text-purple-500 flex-shrink-0" />
                      <span>{t('purchase.benefit_support')}</span>
                    </div>
                  </div>
                </CardContent>
              </Card>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default InvestmentPurchase;

client/src/pages/my-investments.tsx.content:
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { useLocation } from "wouter";
import { useAuth } from "@/hooks/useAuth";
import Navigation from "@/components/navigation";
import { useLanguage } from "@/contexts/LanguageContext";
import { 
  Bitcoin, 
  TrendingUp, 
  TrendingDown,
  Wallet,
  Clock,
  Plus,
  BarChart3,
  Eye
} from "lucide-react";

interface UserInvestment {
  id: string;
  userId: string;
  packageId: string;
  transactionId: string;
  investmentAmount: string;
  currentValue: string | null;
  profitLoss: string | null;
  profitLossPercentage: string | null;
  bitcoinCode: string;
  status: string;
  startDate: string;
  endDate: string | null;
  lastUpdated: string;
  metadata: string | null;
  package: {
    id: string;
    name: string;
    minInvestment: string;
    minRate: string;
    maxRate: string;
    features: string[];
    recommended: number;
  };
}

function MyInvestments() {
  const { t, language } = useLanguage();
  const [, setLocation] = useLocation();
  const { user, isAuthenticated } = useAuth();

  // Get user investments
  const { data: investments = [], isLoading, error } = useQuery({
    queryKey: ["/api/user-investments"],
    enabled: !!isAuthenticated,
  });

  const formatCurrency = (amount: string | null) => {
    if (!amount) return "N/A";
    const locale = language === 'vi' ? 'vi-VN' : 'en-US';
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency: 'VND'
    }).format(parseFloat(amount));
  };

  const formatDate = (dateString: string) => {
    const locale = language === 'vi' ? 'vi-VN' : 'en-US';
    return new Date(dateString).toLocaleDateString(locale, {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
    });
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'active':
        return <Badge className="bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200">{t('my_investments.status.active')}</Badge>;
      case 'completed':
        return <Badge className="bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200">{t('my_investments.status.completed')}</Badge>;
      case 'cancelled':
        return <Badge variant="destructive">{t('my_investments.status.cancelled')}</Badge>;
      default:
        return <Badge variant="secondary">{status}</Badge>;
    }
  };

  const getTotalInvestment = () => {
    return (investments as UserInvestment[]).reduce((total, inv) => total + parseFloat(inv.investmentAmount || '0'), 0);
  };

  const getTotalCurrentValue = () => {
    return (investments as UserInvestment[]).reduce((total, inv) => total + parseFloat(inv.currentValue || inv.investmentAmount || '0'), 0);
  };

  const getTotalProfit = () => {
    return (investments as UserInvestment[]).reduce((total, inv) => total + parseFloat(inv.profitLoss || '0'), 0);
  };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-orange-50 to-blue-50 dark:from-gray-900 dark:to-gray-800">
        <Navigation />
        <div className="pt-20 pb-16">
          <div className="container mx-auto px-4">
            <Card className="max-w-md mx-auto">
              <CardHeader className="text-center">
                <CardTitle className="text-2xl font-bold text-orange-600 dark:text-orange-400">
                  {t('my_investments.login_required_title')}
                </CardTitle>
              </CardHeader>
              <CardContent className="text-center space-y-4">
                <p className="text-gray-600 dark:text-gray-300">
                  {t('my_investments.login_required_message')}
                </p>
                <Button onClick={() => setLocation("/login")} className="w-full" data-testid="button-login">
                  {t('my_investments.login_button')}
                </Button>
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-50 to-blue-50 dark:from-gray-900 dark:to-gray-800">
      <Navigation />

      <div className="pt-20 pb-16">
        <div className="container mx-auto px-4">
          {/* Header */}
          <div className="mb-8">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <div>
                <h1 className="text-4xl font-bold text-gray-900 dark:text-white mb-2" data-testid="title-my-investments">
                  {t('my_investments.title')}
                </h1>
                <p className="text-lg text-gray-600 dark:text-gray-300">
                  {t('my_investments.portfolio_overview')}
                </p>
              </div>
              <Button 
                onClick={() => setLocation("/investment-purchase")} 
                className="bg-orange-600 hover:bg-orange-700 text-white"
                data-testid="button-new-investment"
              >
                <Plus className="h-4 w-4 mr-2" />
                {t('my_investments.start_investing')}
              </Button>
            </div>
          </div>

          {/* Summary Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
            <Card>
              <CardContent className="p-6">
                <div className="flex items-center gap-4">
                  <div className="p-3 bg-blue-100 dark:bg-blue-900 rounded-lg">
                    <Wallet className="h-6 w-6 text-blue-600 dark:text-blue-300" />
                  </div>
                  <div>
                    <p className="text-sm text-gray-600 dark:text-gray-400">{t('my_investments.total_invested')}</p>
                    <p className="text-2xl font-bold text-gray-900 dark:text-white" data-testid="text-total-investment">
                      {formatCurrency(getTotalInvestment().toString())}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardContent className="p-6">
                <div className="flex items-center gap-4">
                  <div className="p-3 bg-green-100 dark:bg-green-900 rounded-lg">
                    <TrendingUp className="h-6 w-6 text-green-600 dark:text-green-300" />
                  </div>
                  <div>
                    <p className="text-sm text-gray-600 dark:text-gray-400">{t('my_investments.current_value')}</p>
                    <p className="text-2xl font-bold text-gray-900 dark:text-white" data-testid="text-current-value">
                      {formatCurrency(getTotalCurrentValue().toString())}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardContent className="p-6">
                <div className="flex items-center gap-4">
                  <div className={`p-3 rounded-lg ${
                    getTotalProfit() >= 0 
                      ? 'bg-green-100 dark:bg-green-900' 
                      : 'bg-red-100 dark:bg-red-900'
                  }`}>
                    {getTotalProfit() >= 0 ? (
                      <TrendingUp className="h-6 w-6 text-green-600 dark:text-green-300" />
                    ) : (
                      <TrendingDown className="h-6 w-6 text-red-600 dark:text-red-300" />
                    )}
                  </div>
                  <div>
                    <p className="text-sm text-gray-600 dark:text-gray-400">{t('my_investments.profit_loss')}</p>
                    <p className={`text-2xl font-bold ${
                      getTotalProfit() >= 0 
                        ? 'text-green-600 dark:text-green-400' 
                        : 'text-red-600 dark:text-red-400'
                    }`} data-testid="text-profit-loss">
                      {getTotalProfit() >= 0 ? '+' : ''}{formatCurrency(getTotalProfit().toString())}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Investments List */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2" data-testid="title-investments-list">
                <BarChart3 className="h-5 w-5 text-orange-500" />
                Danh sách đầu tư ({(investments as UserInvestment[]).length})
              </CardTitle>
            </CardHeader>
            <CardContent>
              {isLoading ? (
                <div className="space-y-4">
                  {[1, 2, 3].map((i) => (
                    <div key={i} className="h-32 bg-gray-200 dark:bg-gray-700 rounded-lg animate-pulse" />
                  ))}
                </div>
              ) : error ? (
                <div className="text-center py-12">
                  <p className="text-red-600 dark:text-red-400">Lỗi tải dữ liệu đầu tư</p>
                </div>
              ) : (investments as UserInvestment[]).length === 0 ? (
                <div className="text-center py-12">
                  <Bitcoin className="h-16 w-16 mx-auto mb-4 text-gray-400" />
                  <h3 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
                    Chưa có khoản đầu tư nào
                  </h3>
                  <p className="text-gray-600 dark:text-gray-300 mb-6">
                    Bắt đầu hành trình đầu tư Bitcoin của bạn ngay hôm nay
                  </p>
                  <Button 
                    onClick={() => setLocation("/investment-purchase")}
                    className="bg-orange-600 hover:bg-orange-700 text-white"
                    data-testid="button-start-investing"
                  >
                    <Plus className="h-4 w-4 mr-2" />
                    Bắt đầu đầu tư
                  </Button>
                </div>
              ) : (
                <div className="space-y-4">
                  {(investments as UserInvestment[]).map((investment) => (
                    <Card key={investment.id} className="border border-gray-200 dark:border-gray-700" data-testid={`card-investment-${investment.id}`}>
                      <CardContent className="p-6">
                        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                          {/* Investment Info */}
                          <div className="lg:col-span-2">
                            <div className="flex items-start justify-between mb-3">
                              <div>
                                <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-1">
                                  {investment.package.name}
                                </h3>
                                <p className="text-sm text-gray-600 dark:text-gray-400">
                                  Mã Bitcoin: {investment.bitcoinCode}
                                </p>
                              </div>
                              {getStatusBadge(investment.status)}
                            </div>

                            <div className="grid grid-cols-2 gap-4 text-sm">
                              <div>
                                <p className="text-gray-600 dark:text-gray-400">Ngày đầu tư</p>
                                <p className="font-medium">{formatDate(investment.startDate)}</p>
                              </div>
                              <div>
                                <p className="text-gray-600 dark:text-gray-400">Lợi nhuận dự kiến</p>
                                <p className="font-medium text-green-600 dark:text-green-400">
                                  {investment.package.minRate}% - {investment.package.maxRate}%
                                </p>
                              </div>
                            </div>
                          </div>

                          {/* Financial Info */}
                          <div className="space-y-3">
                            <div>
                              <p className="text-sm text-gray-600 dark:text-gray-400">Số tiền đầu tư</p>
                              <p className="text-lg font-semibold text-gray-900 dark:text-white">
                                {formatCurrency(investment.investmentAmount)}
                              </p>
                            </div>
                            <div>
                              <p className="text-sm text-gray-600 dark:text-gray-400">{t('my_investments.current_value')}</p>
                              <p className="text-lg font-semibold text-gray-900 dark:text-white">
                                {formatCurrency(investment.currentValue || investment.investmentAmount)}
                              </p>
                            </div>
                          </div>

                          {/* Performance & Actions */}
                          <div className="flex flex-col justify-between">
                            <div className="space-y-2">
                              {investment.profitLoss && (
                                <div>
                                  <p className="text-sm text-gray-600 dark:text-gray-400">{t('my_investments.profit_loss')}</p>
                                  <p className={`text-lg font-semibold ${
                                    parseFloat(investment.profitLoss) >= 0 
                                      ? 'text-green-600 dark:text-green-400' 
                                      : 'text-red-600 dark:text-red-400'
                                  }`}>
                                    {parseFloat(investment.profitLoss) >= 0 ? '+' : ''}
                                    {formatCurrency(investment.profitLoss)}
                                  </p>
                                  {investment.profitLossPercentage && (
                                    <p className={`text-sm ${
                                      parseFloat(investment.profitLossPercentage) >= 0 
                                        ? 'text-green-600 dark:text-green-400' 
                                        : 'text-red-600 dark:text-red-400'
                                    }`}>
                                      ({parseFloat(investment.profitLossPercentage) >= 0 ? '+' : ''}
                                      {investment.profitLossPercentage}%)
                                    </p>
                                  )}
                                </div>
                              )}
                            </div>

                            <div className="flex gap-2 pt-4">
                              <Button 
                                variant="outline" 
                                size="sm"
                                onClick={() => setLocation(`/investment-details/${investment.id}`)}
                                data-testid={`button-view-${investment.id}`}
                              >
                                <Eye className="h-4 w-4 mr-1" />
                                Chi tiết
                              </Button>
                            </div>
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

export default MyInvestments;

